css:
.mcq-q { font-weight: 600; line-height: 1.8; white-space: pre-wrap; margin-bottom: 12px; }
.mcq-opts { display: flex; flex-direction: column; gap: 7px; }
.mcq-opt { display: flex; align-items: flex-start; gap: 10px; padding: 9px 12px; border: 1px solid var(--line); border-radius: 10px; background: var(--bg-2); line-height: 1.65; }
.mcq-k { flex: 0 0 auto; width: 20px; height: 20px; margin-top: 2px; border-radius: 50%; background: var(--bg-3); color: var(--fg-2); font-size: 12px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center; }
.mcq-t { flex: 1 1 auto; white-space: pre-wrap; }
.mcq-opt.is-right { border-color: var(--green); background: rgba(34, 197, 94, .12); }
.mcq-opt.is-right .mcq-k { background: var(--green); color: #fff; }
.mcq-mark { flex: 0 0 auto; color: var(--green); font-weight: 700; }
.mcq-answer { margin-top: 12px; padding-top: 10px; border-top: 1px dashed var(--line); color: var(--green); }
.mcq-kp { margin-top: 14px; padding: 9px 12px; border-radius: 10px; background: var(--bg-3); line-height: 1.7; white-space: pre-wrap; }
.mcq-kp b { margin-right: 8px; color: var(--amber); }
.mcq-ex { margin-top: 10px; line-height: 1.8; white-space: pre-wrap; }
.mcq-ex b { display: block; margin-bottom: 4px; color: var(--fg-2); font-size: 13px; }
.mcq-src { margin-top: 10px; color: var(--fg-3); font-size: 12px; }
.fc-card .mcq-opt { border-radius: 8px; }
